// make-app-bundle.js
// Creates a clean deployable folder (quest-board-deploy/) ready for:
//   1. Netlify deploy (drag-and-drop or Git)
//   2. PWABuilder submission to Google Play
//
// RUN: node make-app-bundle.js   (from anywhere — paths resolve via __dirname)
//
// Sources:
//   tools/quest-board.html          ← generated by make-public.js first!
//   tools/quest-board-page.html     ← QuestLog landing page
//   questlog-pwa/                   ← manifest.json, sw.js, privacy-policy.html
//   icons/                          ← icon-192.png, icon-512.png

'use strict';
const fs   = require('fs');
const path = require('path');

const ROOT  = __dirname;
const TOOLS = path.join(ROOT, 'tools');
const PWA   = path.join(ROOT, 'questlog-pwa');
const DEST  = path.join(ROOT, 'quest-board-deploy');
const SITE  = 'https://jvdesignstudio.co.uk';

let hadError = false;
function fail(msg){ console.error('  ✗ ' + msg); hadError = true; }

console.log('\n⚔️  Building QuestLog app bundle...\n');

// ── Helpers ──────────────────────────────────────────────────────────────────
function mkdir(p){ if(!fs.existsSync(p))fs.mkdirSync(p,{recursive:true}); }
function copy(src,dst,label){
  if(!fs.existsSync(src)){ fail('missing source: ' + path.relative(ROOT,src) + (label?' ('+label+')':'')); return false; }
  fs.copyFileSync(src,dst); console.log('  copied ', path.basename(dst)); return true;
}
function copyRewrite(src,dst,replacements,label){
  if(!fs.existsSync(src)){ fail('missing source: ' + path.relative(ROOT,src) + (label?' ('+label+')':'')); return false; }
  let c = fs.readFileSync(src,'utf8');
  let missed = [];
  replacements.forEach(([from,to])=>{
    if(!c.includes(from)) { missed.push(from); return; }
    c = c.split(from).join(to);
  });
  fs.writeFileSync(dst,c);
  console.log('  wrote  ', path.basename(dst), missed.length ? '(⚠ unmatched: '+missed.length+')' : '');
  return true;
}

// ── Create folder structure ──────────────────────────────────────────────────
mkdir(DEST);
mkdir(path.join(DEST,'icons'));
mkdir(path.join(DEST,'.well-known'));

// ── Core: the app itself ─────────────────────────────────────────────────────
console.log('\nCore files:');
copy(path.join(TOOLS,'quest-board.html'), path.join(DEST,'index.html'), 'run node make-public.js first');

// ── PWA assets (canonical sources in questlog-pwa/) ─────────────────────────
copy(path.join(PWA,'manifest.json'),        path.join(DEST,'manifest.json'));
copy(path.join(PWA,'sw.js'),                path.join(DEST,'sw.js'));
copyRewrite(
  path.join(PWA,'privacy-policy.html'),
  path.join(DEST,'privacy-policy.html'),
  [['href="quest-board.html"','href="index.html"']]
);

// ── Landing page (rewired so every link works from the bundle root) ─────────
console.log('\nLanding page:');
copyRewrite(
  path.join(TOOLS,'quest-board-page.html'),
  path.join(DEST,'quest-board-page.html'),
  [
    // App CTA → bundled app
    ['href="quest-board.html"',            'href="index.html"'],
    // Sibling tools only exist on the main site
    ['href="icon-generator.html"',         'href="'+SITE+'/tools/icon-generator.html"'],
    ['href="../pages/dev-tools.html',      'href="'+SITE+'/pages/dev-tools.html'],
    // Shared assets are bundled locally at root
    ['href="../logo.png',                  'href="/logo.png'],
    ['href="../style-shared.css',          'href="/style-shared.css'],
    ['src="../analytics-loader.js',        'src="/analytics-loader.js'],
    // Site chrome (nav/footer) points back at the main site
    ['href="/index.html',                  'href="'+SITE+'/index.html'],
    ['href="/pages/',                      'href="'+SITE+'/pages/'],
    ['href="/workshops/',                  'href="'+SITE+'/workshops/']
  ]
);

// ── Shared assets used by app + landing ──────────────────────────────────────
console.log('\nShared assets:');
copy(path.join(ROOT,'logo.png'),              path.join(DEST,'logo.png'));
copy(path.join(ROOT,'style-shared.css'),      path.join(DEST,'style-shared.css'));
copy(path.join(ROOT,'analytics-loader.js'),   path.join(DEST,'analytics-loader.js'));
copy(path.join(ROOT,'cookie-consent.js'),     path.join(DEST,'cookie-consent.js'));

// ── Icons ────────────────────────────────────────────────────────────────────
console.log('\nIcons:');
['icon-192.png','icon-512.png'].forEach(icon => {
  copy(path.join(ROOT,'icons',icon), path.join(DEST,'icons',icon));
});

// ── Digital Asset Links (fill in after getting your Play Console SHA) ─────────
fs.writeFileSync(
  path.join(DEST,'.well-known','assetlinks.json'),
  JSON.stringify([{
    relation: ['delegate_permission/common.handle_all_urls'],
    target: {
      namespace: 'android_app',
      package_name: 'com.jvdesignstudio.questlog',
      sha256_cert_fingerprints: ['PASTE_YOUR_SHA256_FINGERPRINT_HERE']
    }
  }], null, 2)
);
console.log('  wrote   .well-known/assetlinks.json  (placeholder SHA — update after Play Console upload)');

// ── Netlify redirects ────────────────────────────────────────────────────────
fs.writeFileSync(path.join(DEST,'_redirects'), [
  '/quest-board  /index.html  200',
  '/app          /index.html  200',
  '/privacy      /privacy-policy.html  200'
].join('\n'));
console.log('  wrote   _redirects');

// ── Report ────────────────────────────────────────────────────────────────────
console.log('\n─────────────────────────────────────────────────────────────');
if(hadError){
  console.log('\n❌ Bundle INCOMPLETE — fix the missing sources above and re-run.\n');
  process.exitCode = 1;
} else {
  console.log('\n✅ Bundle ready at: quest-board-deploy/\n');
  console.log('NEXT STEPS:');
  console.log('  1. Deploy: netlify.com → Add new site → Deploy manually → drag quest-board-deploy/');
  console.log('  2. Test:   https://pagespeed.web.dev → Lighthouse PWA score 80+ ');
  console.log('  3. Play:   pwabuilder.com → Package for stores → Google Play → .aab');
  console.log('  4. Console: upload .aab → copy SHA256 → paste into .well-known/assetlinks.json → redeploy');
}

// List the bundle contents
console.log('\nBundle contents:');
function listDir(dir, prefix=''){
  fs.readdirSync(dir).forEach(f=>{
    const full=path.join(dir,f);
    const stat=fs.statSync(full);
    if(stat.isDirectory()) listDir(full,prefix+'  '+f+'/');
    else console.log('  '+prefix+f+' ('+Math.round(stat.size/1024)+'KB)');
  });
}
listDir(DEST);
console.log('─────────────────────────────────────────────────────────────\n');
